// CIP-KGE Stage 1 (binding layer): extract the local sub-graph for the target node.
// Input: $json = full contentIndex dict (from Fetch Knowledge Graph).
// The sub-graph = target node + immediate dependencies (outbound + inbound links).

const index = $json;
const body = $('Session Start Webhook').item.json.body || {};
const targetId = body.target_node_id;

if (!targetId) {
  throw new Error('target_node_id missing in webhook body. Required: {session_id, target_node_id, transcript?}');
}
const target = index[targetId];
if (!target) {
  throw new Error(`target_node_id '${targetId}' not found in knowledge graph (${Object.keys(index).length} nodes loaded)`);
}

// Same numbered-header parser as bindings/pyragogy/import_graph.py.
// Node content in contentIndex.json is plain text: "1. Definition", "2. Use Case", ...
const SECTION_MAP = { '1': 'definition', '2': 'use_case', '3': 'human_role', '4': 'ai_role', '5': 'friction', '6': 'risk', '7': 'observable_markers' };
const HEADER_RE = /^\s*([1-7])\.\s+(Definition|Use\s*Case|Human\s*Role|AI\s*Role|Friction|Risk|Observable\s*Markers)\s*:?\s*$/gim;

function parseSections(content) {
  const matches = [...content.matchAll(HEADER_RE)];
  if (matches.length === 0) return { body: content.trim() };
  const sections = {};
  matches.forEach((m, i) => {
    const start = m.index + m[0].length;
    const end = i + 1 < matches.length ? matches[i + 1].index : content.length;
    sections[SECTION_MAP[m[1]]] = content.slice(start, end).trim();
  });
  return sections;
}

const outbound = (target.links || []).filter(l => index[l]);
const inbound = Object.keys(index).filter(s => (index[s].links || []).includes(targetId));
const neighborIds = [...new Set([...outbound, ...inbound])];

return {
  json: {
    session_id: body.session_id || 'session-UNKNOWN',
    target_node_id: targetId,
    graph_source_url: body.graph_url || 'https://syllabus.pyragogy.org/static/contentIndex.json',
    fetched_at: new Date().toISOString(),
    target_node: {
      node_id: targetId,
      title: target.title || targetId,
      tags: target.tags || [],
      sections: parseSections(target.content || '')
    },
    neighbor_summaries: neighborIds.map(id => ({
      node_id: id,
      title: index[id].title || id,
      content_preview: (index[id].content || '').slice(0, 400)
    })),
    all_slugs: Object.keys(index)
  }
};

// Prepares the TruGen interview agent config for THIS node (Stage 2 setup).
// The graph data passes through untouched for the downstream Stage 3 analysis.

const target = $json.target_node;

const sectionList = Object.entries(target.sections)
  .map(([name, text]) => `## ${name}\n${text}`)
  .join('\n\n');

const systemPrompt = `You are the Pyragogy Cognitive Interviewer (CIP-KGE protocol).
You are interviewing an expert about ONE node of the Pyragogy Syllabus knowledge graph: "${target.title}" (${target.node_id}).

The interview is NOT about discovering what the node says — it is about finding where it is incomplete, imprecise, or wrong.

CURRENT PUBLISHED STATE OF THE NODE:
${sectionList}

Use the five question types: Q1 Elicitation (surface knowledge), Q2 Clarification (make statements precise and operationalizable), Q3 Socratic (test premises, constructive adversary), Q4 Contrastive (boundaries vs. related concepts), Q5 Mapping (relationships to other nodes).

What you MUST NOT do:
- Do not summarize the interviewee's words back to them during the session.
- Do not suggest answers (e.g., "Would you say the risk here is X?" contaminates the evidence).
- Do not close topics on a thin answer — return with a different question type.
- Do not ask what the node SHOULD say. Ask what they know about the phenomenon.

Every exchange is numbered. The output of this session is a Knowledge Diff subject to human review.`;

return {
  json: {
    ...$json,
    agentName: 'Pyragogy Cognitive Interviewer',
    welcomeMessage: `I'm holding the current published version of "${target.title}". I'm not here to lecture you — I'm here to find where this node is incomplete, imprecise, or wrong, using your experience. Shall we start from the real-world context where you encountered this?`,
    systemPrompt
  }
};

