// Stage 5 (automated part): validate the LLM-produced draft against the
// seven-section contract AND against the actual published baseline.
// A candidate change whose current_text does not match the published section
// is REJECTED here — this is the check that prevents stale-context edits.

let raw = $json.message?.content || $json.output || $json.text || '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();

const errors = [];
const checks = { current_text_match: [] };
let candidate = null;
try {
  candidate = JSON.parse(raw);
} catch (e) {
  errors.push('JSON parsing failed: ' + e.message);
}

const SECTIONS = ['definition', 'use_case', 'human_role', 'ai_role', 'friction', 'risk', 'observable_markers'];
const OPS = ['modify', 'append', 'remove_sentence'];

// Same normalization as the binding: typographic quotes/dashes and whitespace
// must not defeat the comparison with the published text.
function norm(s) {
  return (s || '')
    .normalize('NFKC')
    .replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u2011\u2013\u2014]/g, '-')
    .replace(/\s+/g, ' ').trim();
}

const baselineSections = $json.target_node?.sections || {};
const changes = candidate?.candidate_changes || [];

if (candidate) {
  if (!Array.isArray(changes) || changes.length === 0) errors.push('candidate_changes must be a non-empty array');
  if (changes.length > 3) errors.push(`Bounded Modification violated: ${changes.length} changes (max 3)`);

  changes.forEach((c, i) => {
    const label = `change[${i}]`;
    if (!SECTIONS.includes(c.section)) errors.push(`${label}: unknown section '${c.section}'`);
    if (!OPS.includes(c.operation)) errors.push(`${label}: unknown operation '${c.operation}'`);
    if (!c.proposed_text || !c.proposed_text.trim()) errors.push(`${label}: empty proposed_text`);
    if (!c.rationale || !c.rationale.trim()) errors.push(`${label}: empty rationale`);
    if (!Array.isArray(c.exchange_refs) || c.exchange_refs.length === 0) {
      errors.push(`${label}: no exchange_refs — Traceability Constraint (Invariant 1)`);
    }
    if (c.operation !== 'append') {
      if (!c.current_text || !c.current_text.trim()) {
        errors.push(`${label}: current_text required for ${c.operation}`);
      } else {
        const published = baselineSections[c.section];
        const match = published !== undefined && norm(published) === norm(c.current_text);
        checks.current_text_match.push({ index: i, section: c.section, match });
        if (!published) errors.push(`${label}: section '${c.section}' not present in published node`);
        else if (!match) errors.push(`${label}: current_text does NOT match published '${c.section}' section (stale or paraphrased)`);
      }
    }
  });
}

return {
  json: {
    ...$json,
    draft: candidate,
    _validation: { isValid: errors.length === 0, errors, checks }
  }
};

// Relation consistency: every detected relation must resolve to a real node
// of the graph. Self-references are rejected.

const known = new Set($json.all_slugs || []);
const relations = $json.draft?.detected_relations || [];
const errors = [];
const warnings = [];

relations.forEach(r => {
  if (r === $json.target_node_id) errors.push(`self-reference: relation '${r}' points to the target node itself`);
  else if (!known.has(r)) errors.push(`relation target '${r}' does not exist in the knowledge graph`);
});

return {
  json: {
    ...$json,
    relation_consistency: {
      isValid: errors.length === 0,
      errors,
      warnings,
      checked: relations
    }
  }
};

// CIP-KGE v0.3 — Stage 3 output: DRAFT Knowledge Diff for human review.
//
// EPISTEMIC GATE — DO NOT REPLACE THIS NODE WITH A WRITE OPERATION.
// Principle 3: "AI proposes; humans validate." Principle 4: "Interviews generate diffs, not edits."
// The output must be saved under diffs/ and reviewed by a human (Stages 5-8) before any graph is touched.

const now = new Date();
const dateStr = now.toISOString().slice(0, 10);
const changes = ($json.draft?.candidate_changes || []).map(c => ({
  section: c.section,
  operation: c.operation,
  ...(c.operation !== 'append' ? { current_text: c.current_text } : {}),
  proposed_text: c.proposed_text,
  rationale: c.rationale
}));

const allRefs = [...new Set(($json.draft?.candidate_changes || []).flatMap(c => c.exchange_refs || []))].sort();
const sessionId = $json.session_id;
const exchangeRef = allRefs.length > 0 ? `${sessionId}/${allRefs.join(',')}` : null;

const shapeOk = $json._validation?.isValid === true;
const relationsOk = $json.relation_consistency?.isValid === true;
const passes = shapeOk && relationsOk && exchangeRef !== null;

const draftDiff = {
  id: `diff-${dateStr}-DRAFT`,          // human assigns the final NNN; schema rejects '-DRAFT' until finalized — intentional
  protocol_version: 'CIP-KGE-v0.3',
  session_id: sessionId,
  generated_at: now.toISOString(),
  status: 'DRAFT — NOT SUBMITTED',
  target: { node_id: $json.target_node_id, operation: 'modify' },
  section_changes: changes,
  evidence: {
    session_exchange_ref: exchangeRef,
    summary: $json.draft?.extraction_notes || 'Automated Stage 3 extraction — human reviewer must verify against the transcript.',
    confidence: 'low',
    confidence_rationale: 'Machine-extracted candidates: current_text verified against published baseline, but exchange-level grounding requires human transcript review.',
    corroboration_scope: allRefs.length > 1 ? 'intra_session' : 'none',
    linked_sessions: []
  },
  pre_review_check: {
    passes_minimum_quality: passes,
    failure_reason: passes ? null : (!exchangeRef ? 'no_evidence' : (!shapeOk ? 'yaml_schema_invalid' : 'relation_target_missing'))
  },
  review_status: 'proposed',
  review_notes: [],
  merge_ready: false,
  pr_url: null
};

return {
  json: {
    status: passes ? 'draft_ready_for_human_review' : 'draft_incomplete_human_review_required',
    write_performed: false,
    message: 'Stage 3 complete. NO graph write occurred — a human must verify exchange grounding, finalize the diff id, and run Stages 5-8 (validate_diff.py, review, transformation, PR).',
    baseline_anchor: { graph_source_url: $json.graph_source_url, fetched_at: $json.fetched_at },
    automated_checks: { shape: $json._validation, relations: $json.relation_consistency },
    draft_diff: draftDiff,
    generatedAt: now.toISOString()
  }
};

return {
  json: {
    status: 'error',
    error_type: 'AUTOMATED_CHECKS_FAILED',
    shape_validation: $json._validation || null,
    relation_consistency: $json.relation_consistency || null,
    write_performed: false,
    timestamp: new Date().toISOString()
  }
};
